// Admin › Outline › "Webhook": the endpoint Outline calls when pages change, so
// Solvro can show "Mentioned in Outline". The signing secret is generated by
// Solvro, stored encrypted, and shown exactly once here
// (docs/archive/plans/outline-integration.md, F10 / D4: only page id, title and
// the Solvro links found are kept - never page text).
import { useState } from "react";
import { CopyField } from "@/components/admin/CopyField";
import { ConfirmModal } from "@/components/ConfirmModal";
import { Modal } from "@/components/Modal";
import { Alert, AlertDescription } from "@/components/reui/alert";
import { Chip } from "@/components/StatusChip";
import { ApiError } from "@/lib/api";
import { fmtAgo } from "@/lib/formatDate";
import { WEBHOOK_STALE_COPY, webhookHealth } from "@/lib/outlineDocs";
import { useRotateOutlineWebhookSecret, type OutlineAdminSettings } from "@/lib/queries";

const LABEL = "mb-1 block font-display text-label-caps uppercase text-on-surface-variant";

export function OutlineWebhookCard({ settings }: { settings: OutlineAdminSettings }) {
  const rotate = useRotateOutlineWebhookSecret();
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [secret, setSecret] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const health = webhookHealth(settings.lastWebhookAt);
  const receiving = settings.webhookSecretSet && health === "ok";

  // Drop the plaintext from component state and the mutation cache as soon as the dialog closes.
  function closeSecret() {
    setSecret(null);
    rotate.reset();
  }

  async function generate() {
    setError(null);
    setConfirmOpen(false);
    try {
      const res = await rotate.mutateAsync();
      setSecret(res.webhookSecret);
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Could not generate the signing secret.");
    }
  }

  return (
    <section
      aria-label="Webhook"
      data-testid="outline-webhook-card"
      className="space-y-4 rounded-sm border border-outline-variant bg-surface-container-lowest p-4"
    >
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap items-center gap-2">
          <h3 className="font-display text-sm font-semibold text-on-surface">
            Webhook (for “Mentioned in Outline”)
          </h3>
          <Chip tone={receiving ? "emerald" : settings.webhookSecretSet ? "amber" : "gray"}>
            {receiving ? "Receiving" : settings.webhookSecretSet ? "Waiting" : "Not set up"}
          </Chip>
          <span className="text-xs text-on-surface-variant" data-testid="outline-last-delivery">
            {settings.lastWebhookAt
              ? `· last delivery ${fmtAgo(settings.lastWebhookAt)}`
              : "· no delivery yet"}
          </span>
        </div>
        <button
          type="button"
          onClick={() => (settings.webhookSecretSet ? setConfirmOpen(true) : void generate())}
          disabled={rotate.isPending}
          data-testid="outline-rotate-secret"
          className="rounded-sm border border-outline-variant px-3 py-1.5 font-display text-xs font-semibold text-on-surface hover:bg-surface-container disabled:opacity-50"
        >
          {rotate.isPending
            ? "Generating…"
            : settings.webhookSecretSet
              ? "Rotate secret"
              : "Generate secret"}
        </button>
      </div>

      <p className="text-sm text-on-surface-variant">
        In Outline, add a webhook under Settings › Webhooks with this URL and the signing secret.
        Events: <code className="font-mono text-meta">documents.publish</code>,{" "}
        <code className="font-mono text-meta">documents.update</code>,{" "}
        <code className="font-mono text-meta">documents.title_change</code>,{" "}
        <code className="font-mono text-meta">documents.archive</code>,{" "}
        <code className="font-mono text-meta">documents.delete</code>. Solvro keeps only the page
        id, title and the Solvro links it finds — never the page text. If Outline and Solvro run
        on the same private network, set{" "}
        <code className="font-mono text-meta">ALLOWED_PRIVATE_IP_ADDRESSES</code> for Outline,
        which refuses private addresses by default.
      </p>

      {error && (
        <div role="alert" className="rounded-sm border border-error/40 bg-error/10 px-3 py-2 text-sm text-error">
          {error}
        </div>
      )}

      {settings.webhookSecretSet && health !== "ok" && (
        <Alert variant="warning" data-testid="outline-webhook-warning">
          <AlertDescription>
            <p>
              {health === "never"
                ? "No delivery yet — add the webhook in Outline with the URL and signing secret, then edit any page to test it."
                : WEBHOOK_STALE_COPY}
            </p>
          </AlertDescription>
        </Alert>
      )}

      <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
        <div>
          <div className={LABEL}>Webhook URL</div>
          {settings.webhookUrl ? (
            <CopyField value={settings.webhookUrl} label="webhook URL" testId="outline-webhook-url" />
          ) : (
            <p className="text-sm text-on-surface-variant">
              Available once the server has an <code className="font-mono text-meta">APP_URL</code>.
            </p>
          )}
        </div>
        <div>
          <div className={LABEL}>Signing secret</div>
          <p className="text-sm text-on-surface-variant" data-testid="outline-webhook-secret-state">
            {settings.webhookSecretSet
              ? "Stored encrypted · shown once when generated"
              : "Not generated yet"}
          </p>
        </div>
      </div>

      <ConfirmModal
        open={confirmOpen}
        onClose={() => setConfirmOpen(false)}
        onConfirm={() => void generate()}
        title="Rotate the signing secret?"
        body="The current secret stops working immediately. Paste the new one into the webhook in Outline, or deliveries are rejected until you do."
        confirmLabel="Rotate secret"
        confirmTone="warning"
        busy={rotate.isPending}
      />

      <Modal
        open={secret !== null}
        onClose={closeSecret}
        title="New signing secret"
        footer={
          <button
            type="button"
            onClick={closeSecret}
            data-testid="outline-secret-done"
            className="rounded-sm bg-primary px-4 py-1.5 font-display text-xs font-semibold text-on-primary hover:bg-primary-container"
          >
            Done
          </button>
        }
      >
        <div className="space-y-3">
          <p className="text-sm text-on-surface">
            Copy this secret into the webhook's signing secret field in Outline now.{" "}
            <strong>You won't see it again.</strong>
          </p>
          {secret && <CopyField value={secret} label="signing secret" testId="outline-new-secret" />}
          <p className="text-xs text-on-surface-variant">
            If you lose it, rotate the secret to generate a new one.
          </p>
        </div>
      </Modal>
    </section>
  );
}
